    "src/AaveVault.sol": {
      "content": "// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

import "./interfaces/IEVMEntry.sol";
import {IVault} from "./interfaces/IVault.sol";
import "./utils/AaveVaultStorage.sol";
import {Protocol} from "./utils/Types.sol";
import {IPool} from "@aave/contracts/interfaces/IPool.sol";
import "@openzeppelin/contracts/proxy/utils/Initializable.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {Strings} from "@openzeppelin/contracts/utils/Strings.sol";
import {MessageHashUtils} from "@openzeppelin/contracts/utils/cryptography/MessageHashUtils.sol";
import {SignatureChecker} from "@openzeppelin/contracts/utils/cryptography/SignatureChecker.sol";
import {Math} from "@openzeppelin/contracts/utils/math/Math.sol";
import {Callable, MessageContext} from "@zetachain/contracts/evm/interfaces/IGatewayEVM.sol";

/**
 * @title AaveVault
 * @author https://github.com/nzmpi
 * @notice A vault for the Aave protocol.
 * @dev Can only be called from ZetaChain or EVMEntry.
 */
contract AaveVault is IVault, AaveVaultStorage, Callable, Initializable {
    using SafeERC20 for IERC20;
    using Math for uint256;
    using MessageHashUtils for *;
    using SignatureChecker for address;
    using Strings for uint256;

    /// denominator for fee, 10000 == 100%
    uint256 internal constant SCALE = 10000;
    /// gas savings
    uint256 internal immutable CHAIN_ID = block.chainid;
    IPool internal immutable POOL;
    /// @inheritdoc IVault
    string public constant VERSION = "1.2.1";
    /// @inheritdoc IVault
    IERC20 public immutable TOKEN;
    /// @inheritdoc IVault
    IERC20 public immutable ASSET;
    /// @inheritdoc IVault
    IGatewayEVM public immutable GATEWAY;
    /// @inheritdoc IVault
    address public immutable YIELDMIL;
    /// @inheritdoc IVault
    address public immutable EVMENTRY;

    modifier onlyGateway() {
        if (msg.sender != address(GATEWAY)) revert NotGateway();
        _;
    }

    modifier onlyOwner() {
        if (msg.sender != _getStorage().owner) revert NotOwner();
        _;
    }

    modifier onlyEVMEntry() {
        if (msg.sender != EVMENTRY) revert NotEVMEntry();
        _;
    }

    modifier onlyGuardian() {
        if (!_getStorage().guardians[msg.sender]) revert NotGuardian();
        _;
    }

    constructor(IPool _pool, IERC20 _token, IERC20 _asset, IGatewayEVM _gateway, address _yieldMil, address _evmentry)
        payable
    {
        _disableInitializers();
        if (
            address(_pool) == address(0) || address(_token) == address(0) || address(_asset) == address(0)
                || address(_gateway) == address(0) || _yieldMil == address(0) || _evmentry == address(0)
        ) revert ZeroAddress();
        POOL = _pool;
        TOKEN = _token;
        ASSET = _asset;
        GATEWAY = _gateway;
        YIELDMIL = _yieldMil;
        EVMENTRY = _evmentry;
    }

    /// @inheritdoc Callable
    function onCall(MessageContext calldata context, bytes calldata message)
        external
        payable
        onlyGateway
        returns (bytes memory)
    {
        if (context.sender != YIELDMIL) revert NotYieldMil();
        if (message[0] == hex"01") {
            _deposit(address(GATEWAY), message[1:message.length]);
        } else if (message[0] == hex"02") {
            _withdraw(message[1:message.length]);
        } else {
            revert InvalidMessage(message);
        }
        return "";
    }

    /// @inheritdoc IVault
    function deposit(bytes calldata message) external onlyEVMEntry returns (uint256 shares) {
        shares = _deposit(EVMENTRY, message);
    }

    /// @inheritdoc IVault
    function withdraw(bytes calldata message) external onlyEVMEntry {
        _withdraw(message);
    }

    /**
     * Reinitializes the vault for new versions.
     * @param reInitContext - The reinitialization context.
     */
    function reinitialize(ReInitContext calldata reInitContext)
        external
        payable
        onlyOwner
        reinitializer(reInitContext.version)
    {
        // remove approvals
        IERC20(TOKEN).approve(address(POOL), 0);
        IERC20(TOKEN).approve(address(GATEWAY), 0);

        uint256 len = reInitContext.guardians.length;
        address guardian;
        for (uint256 i; i < len; ++i) {
            guardian = reInitContext.guardians[i];
            if (guardian == address(0)) revert ZeroAddress();
            _getStorage().guardians[guardian] = true;
            emit GuardianUpdated(guardian, true);
        }
    }

    /// @inheritdoc IVault
    function pauseDeposit() external onlyGuardian {
        _getStorage().isDepositPaused = true;
        emit DepositPaused(msg.sender, block.timestamp);
    }

    /// @inheritdoc IVault
    function pauseWithdraw() external onlyGuardian {
        _getStorage().isWithdrawPaused = true;
        emit WithdrawPaused(msg.sender, block.timestamp);
    }

    /// @inheritdoc IVault
    function unpauseDeposit() external payable onlyOwner {
        delete _getStorage().isDepositPaused;
        emit DepositUnpaused(block.timestamp);
    }

    /// @inheritdoc IVault
    function unpauseWithdraw() external payable onlyOwner {
        delete _getStorage().isWithdrawPaused;
        emit WithdrawUnpaused(block.timestamp);
    }

    /// @inheritdoc IVault
    function updateGuardian(address guardian, bool status) external payable onlyOwner {
        _getStorage().guardians[guardian] = status;
        emit GuardianUpdated(guardian, status);
    }

    /// @inheritdoc IVault
    function setFee(uint256 newFee) external payable onlyOwner {
        _accrueYield();
        // cannot be more than 50%
        if (newFee > SCALE / 2) revert InvalidFee();
        _getStorage().fee = uint16(newFee);

        emit FeeUpdated(newFee);
    }

    /// @inheritdoc IVault
    function withdrawFees(address to) external payable onlyOwner {
        _accrueYield();
        Storage storage s = _getStorage();
        uint256 amount = s.accumulatedFees;
        delete s.accumulatedFees;
        ASSET.safeTransfer(to, amount);
        s.lastVaultBalance = ASSET.balanceOf(address(this));

        emit FeesWithdrawn(to, amount);
    }

    /// @inheritdoc IVault
    function transferOwnership(address newOwner) external payable onlyOwner {
        if (newOwner == address(0)) revert ZeroAddress();
        _getStorage().owner = newOwner;

        emit OwnerUpdated(newOwner);
    }

    /// @inheritdoc IVault
    function rescueFunds(address to, IERC20 token, uint256 amount) external payable onlyOwner {
        if (to == address(0)) revert ZeroAddress();
        if ((token == ASSET || token == TOKEN) && !(_getStorage().isDepositPaused && _getStorage().isWithdrawPaused)) {
            revert VaultIsNotPaused();
        }
        emit FundsRescued(to, token, amount);

        if (address(token) == address(0)) {
            (bool s,) = to.call{value: amount}("");
            if (!s) revert TransferFailed();
        } else {
            token.safeTransfer(to, amount);
        }
    }

    /// @inheritdoc IVault
    function getPool() external view returns (address) {
        return address(POOL);
    }

    /// @inheritdoc IVault
    function getFee() external view returns (uint256) {
        return _getStorage().fee;
    }

    /// @inheritdoc IVault
    function getOwner() external view returns (address) {
        return _getStorage().owner;
    }

    /// @inheritdoc IVault
    function isGuardian(address guardian) external view returns (bool) {
        return _getStorage().guardians[guardian];
    }

    /// @inheritdoc IVault
    function getAssetsAndShares(address owner) external view returns (uint256 assets, uint256 shares) {
        shares = _getStorage().shareBalanceOf[owner];
        assets = _convertToAssets(shares);
    }

    /// @inheritdoc IVault
    function getLastVaultBalance() external view returns (uint256) {
        return _getStorage().lastVaultBalance;
    }

    /// @inheritdoc IVault
    function getNonce(address sender) external view returns (uint256) {
        return _getStorage().nonces[sender];
    }

    /// @inheritdoc IVault
    function totalSupply() public view returns (uint256) {
        return _getStorage().totalShares;
    }

    /// @inheritdoc IVault
    function totalAssets() public view returns (uint256) {
        return ASSET.balanceOf(address(this)) - getAccumulatedFees();
    }

    /// @inheritdoc IVault
    function getAccumulatedFees() public view returns (uint256) {
        Storage storage s = _getStorage();
        uint256 newVaultBalance = ASSET.balanceOf(address(this));
        uint256 lastVaultBalance = s.lastVaultBalance;
        uint256 fee = s.fee;
        if (newVaultBalance <= lastVaultBalance || fee == 0) {
            return s.accumulatedFees;
        }

        uint256 newYield = newVaultBalance - lastVaultBalance;
        uint256 newFees = newYield.mulDiv(fee, SCALE, Math.Rounding.Floor);

        return s.accumulatedFees + newFees;
    }

    /**
     * Accrues yield.
     */
    function _accrueYield() internal {
        Storage storage s = _getStorage();
        uint256 newVaultBalance = ASSET.balanceOf(address(this));
        uint256 lastVaultBalance = s.lastVaultBalance;

        if (newVaultBalance <= lastVaultBalance) {
            return;
        }

        uint256 fee = s.fee;
        if (fee != 0) {
            uint256 newYield = newVaultBalance - lastVaultBalance;
            uint256 newFeesEarned = newYield.mulDiv(fee, SCALE, Math.Rounding.Floor);
            s.accumulatedFees += uint240(newFeesEarned);
        }

        s.lastVaultBalance = newVaultBalance;
    }

    /**
     * Deposits assets and mints shares.
     * @notice Reverts when deposit is paused.
     * @param sender - Sender - Gateway or EVMEntry.
     * @param message - Message containing depositor, onBehalfOf, amount and originChainId.
     */
    function _deposit(address sender, bytes calldata message) internal returns (uint256 shares) {
        if (_getStorage().isDepositPaused) revert DepositIsForbidden();
        (address depositor, address onBehalfOf, uint256 amount, uint256 originChainId) =
            abi.decode(message, (address, address, uint256, uint256));
        _accrueYield();
        shares = _convertToShares(amount);
        if (shares == 0) revert ZeroShares();

        TOKEN.safeTransferFrom(sender, address(this), amount);
        TOKEN.safeIncreaseAllowance(address(POOL), amount);
        POOL.supply(address(TOKEN), amount, address(this), 0);
        _getStorage().lastVaultBalance = ASSET.balanceOf(address(this));
        _mint(onBehalfOf, shares);

        emit Deposit(depositor, onBehalfOf, sender, amount, shares, originChainId);
    }

    /**
     * Withdraws assets from the pool, burns shares and sends tokens to a receiver or to EVMEntry.
     * @dev If user tries to withdraw more than they have, it will underflow.
     * @notice Reverts when withdraw is paused.
     * @param message - Message containing sender, receiver, shares, destinationChain,
     * deadline and signature.
     */
    function _withdraw(bytes calldata message) internal {
        if (_getStorage().isWithdrawPaused) revert WithdrawIsForbidden();

        (address sender, address receiver, uint256 shares, uint256 destinationChain) = _verifySignature(message);
        _accrueYield();
        uint256 amount = _convertToAssets(shares);
        if (amount == 0) revert ZeroAssets();

        _burn(sender, shares);
        amount = POOL.withdraw(address(TOKEN), amount, address(this));
        _getStorage().lastVaultBalance = ASSET.balanceOf(address(this));
        emit Withdraw(sender, receiver, amount, shares, destinationChain);

        if (destinationChain == CHAIN_ID) {
            TOKEN.safeTransfer(receiver, amount);
        } else {
            TOKEN.safeIncreaseAllowance(EVMENTRY, amount);
            bytes memory vaultMessage = abi.encode(sender, receiver, destinationChain);
            IEVMEntry(EVMENTRY).onCallback(sender, Protocol.Aave, address(TOKEN), amount, vaultMessage);
        }
    }

    /**
     * Mints shares for the receiver.
     */
    function _mint(address receiver, uint256 amount) internal {
        Storage storage s = _getStorage();
        s.totalShares += amount;
        s.shareBalanceOf[receiver] += amount;
    }

    /**
     * Burns shares for the receiver.
     */
    function _burn(address receiver, uint256 amount) internal {
        Storage storage s = _getStorage();
        s.totalShares -= amount;
        s.shareBalanceOf[receiver] -= amount;
    }

    /**
     * Verifies signature.
     * @param message - Message containing CallContext.
     * @return sender, receiver, shares, destinationChain
     */
    function _verifySignature(bytes calldata message) internal returns (address, address, uint256, uint256) {
        CallContext memory context = abi.decode(message, (CallContext));
        if (context.deadline < block.timestamp) revert SignatureExpired();

        address sender = context.sender;
        uint256 nonce = _getStorage().nonces[sender];
        bytes32 digest = keccak256(
            abi.encode(
                sender,
                context.to,
                context.amount,
                context.destinationChain,
                nonce,
                CHAIN_ID,
                context.deadline,
                address(this)
            )
        ).toEthSignedMessageHash();

        if (context.signature.length > 65) {
            digest = bytes(uint256(digest).toHexString()).toEthSignedMessageHash();
        }

        if (!sender.isValidSignatureNow(digest, context.signature)) revert InvalidSignature();

        _getStorage().nonces[sender] = nonce + 1;
        return (sender, context.to, context.amount, context.destinationChain);
    }

    /**
     * Converts assets to shares.
     */
    function _convertToShares(uint256 assets) internal view returns (uint256) {
        uint256 supply = totalSupply();
        return (assets == 0 || supply == 0) ? assets : assets.mulDiv(supply, totalAssets(), Math.Rounding.Floor);
    }

    /**
     * Converts shares to assets.
     */
    function _convertToAssets(uint256 shares) internal view returns (uint256) {
        uint256 supply = totalSupply();
        return (supply == 0) ? shares : shares.mulDiv(totalAssets(), supply, Math.Rounding.Floor);
    }
}
"
    },
    "src/interfaces/IEVMEntry.sol": {
      "content": "// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

import "../utils/Types.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {IPermit2} from "@permit2/interfaces/IPermit2.sol";
import {IGatewayEVM} from "@zetachain/contracts/evm/interfaces/IGatewayEVM.sol";
import {RevertContext} from "@zetachain/contracts/evm/interfaces/IGatewayEVM.sol";

interface IEVMEntry {
    /**
     * A struct to store the context of the reinitialization call.
     * @param version - The version of the reinitialization call.
     * @param guardians - The guardians of the contract.
     */
    struct ReInitContext {
        uint64 version;
        address[] vaults;
    }

    /**
     * Emitted when a deposit is made
     * @param sender - The address of the sender
     * @param context - The deposit call context
     */
    event Deposit(address indexed sender, CallContext context);
    /**
     * Emitted when the deposit is reverted
     * @param revertContext - The revert context
     */
    event DepositReverted(RevertContext revertContext);
    /**
     * Emitted when funds are rescued
     * @param to - The address to send the funds to
     * @param token - The token to rescue
     * @param amount - The amount of funds to rescue
     */
    event FundsRescued(address to, IERC20 token, uint256 amount);
    /**
     * Emitted when the owner is updated
     * @param newOwner - The new owner address
     */
    event OwnerUpdated(address newOwner);
    /**
     * Emitted when the vault is updated
     * @param protocol - The protocol
     * @param token - The token address
     * @param vault - The vault address
     */
    event VaultUpdated(Protocol protocol, address token, address vault);
    /**
     * Emitted when a withdrawal is made
     * @param sender - The address of the sender
     * @param context - The withdrawal call context
     */
    event Withdraw(address indexed sender, CallContext context);
    /**
     * Emitted when the withdrawal is reverted
     * @param revertContext - The revert context
     */
    event WithdrawReverted(RevertContext revertContext);

    error InvalidContext();
    error InvalidRevertMessage(bytes);
    error InvalidVault();
    error NotGateway();
    error NotOwner();
    error NotUSDC();
    error NotVault();
    error NotEVMEntry();
    error NotZeroValue();
    error TransferFailed();
    error ZeroAddress();

    /**
     * Returns the current version of the contract
     */
    function VERSION() external view returns (string memory);
    /**
     * Returns the GATEWAY contract address
     */
    function GATEWAY() external view returns (IGatewayEVM);
    /**
     * Returns the PERMIT2 contract
     */
    function PERMIT2() external view returns (IPermit2);
    /**
     * Returns the YIELDMIL contract address
     */
    function YIELDMIL() external view returns (address);
    /**
     * Returns the USDC contract address
     */
    function USDC() external view returns (address);

    /**
     * Deposits funds into the vault or sends them to Zetachain.
     * @param context - The deposit call context.
     * @return shares - The amount of minted shares.
     */
    function deposit(CallContext calldata context) external returns (uint256 shares);
    /**
     * Withdraws funds from the vault or calls Zetachain to withdraw
     * @param context - The withdrawal call context
     */
    function withdraw(CallContext calldata context) external payable;
    /**
     * Called by a vault to send tokens to Zetachain
     * @param sender - The address of the sender
     * @param protocol - The protocol
     * @param token - The token
     * @param amount - The amount
     * @param vaultMessage - The vault message
     */
    function onCallback(address sender, Protocol protocol, address token, uint256 amount, bytes calldata vaultMessage)
        external;
    /**
     * Updates the vault address
     * @param protocol - The protocol
     * @param token - The token address
     * @param vault - The vault address
     */
    function updateVault(Protocol protocol, address token, address vault) external payable;
    /**
     * Transfers ownership
     * @param newOwner - The new owner address
     */
    function transferOwnership(address newOwner) external payable;
    /**
     * Rescues funds
     * @param to - The address to rescue to
     * @param token - The token to rescue
     * @param amount - The amount of funds to rescue
     */
    function rescueFunds(address to, IERC20 token, uint256 amount) external payable;

    /**
     * Returns the current owner address
     */
    function getOwner() external view returns (address);
    /**
     * Returns the vault address
     * @param protocol - The protocol
     * @param token - The token address
     */
    function getVault(Protocol protocol, address token) external view returns (address);
    /**
     * Gets the assets and shares from all protocols that supports token deposits
     * @notice Returns an array of values for each protocol in the same order as listed in Protocol
     * @notice If a vault is not found, the assets and shares are set to 0
     * @param owner - The address of the owner
     * @param token - The token address
     * @return assets - The amount of assets, e.g. USDC
     * @return shares - The amount of shares in a vault
     */
    function getAssetsAndShares(address owner, address token)
        external
        view
        returns (uint256[] memory assets, uint256[] memory shares);
}
"
    },
    "src/interfaces/IVault.sol": {
      "content": "// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {IGatewayEVM} from "@zetachain/contracts/evm/interfaces/IGatewayEVM.sol";

/**
 * @title IVault
 * @author https://github.com/nzmpi
 * @notice An interface for a basic vault
 */
interface IVault {
    /**
     * A struct to store the context of the reinitialization call.
     * @param version - The version of the reinitialization call.
     * @param guardians - The guardians of the contract.
     */
    struct ReInitContext {
        uint64 version;
        address[] guardians;
    }

    /**
     * Emitted when a deposit is made.
     * @param depositor - The address of the depositor.
     * @param onBehalfOf - The address on behalf of which the deposit is made.
     * @param sender - The address of the token sender - Gateway or EVMEntry.
     * @param assets - The amount of assets deposited.
     * @param shares - The amount of shares minted.
     * @param chainId - The original chain ID.
     */
    event Deposit(
        address indexed depositor,
        address indexed onBehalfOf,
        address indexed sender,
        uint256 assets,
        uint256 shares,
        uint256 chainId
    );
    /**
     * Emitted when the deposit is paused.
     * @param guardian - The address of the guardian who paused the deposit.
     * @param time - The timestamp when the deposit was paused.
     */
    event DepositPaused(address indexed guardian, uint256 time);
    /**
     * Emitted when the deposit is unpaused.
     * @param time - The timestamp when the deposit was unpaused.
     */
    event DepositUnpaused(uint256 time);
    /**
     * Emitted when the fee is updated.
     * @param newFee - The new fee.
     */
    event FeeUpdated(uint256 newFee);
    /**
     * Emitted when fees are withdrawn.
     * @param to - The address to withdraw to.
     * @param amount - The amount of fees withdrawn.
     */
    event FeesWithdrawn(address indexed to, uint256 amount);
    /**
     * Emitted when funds are rescued.
     * @param to - The address to rescue to.
     * @param token - The token rescued.
     * @param amount - The amount of funds rescued.
     */
    event FundsRescued(address indexed to, IERC20 indexed token, uint256 amount);
    /**
     * Emitted when a guardian is updated.
     * @param guardian - The address of the guardian.
     * @param status - The status of the guardian.
     */
    event GuardianUpdated(address indexed guardian, bool status);
    /**
     * Emitted when the owner is updated.
     * @param newOwner - The new owner.
     */
    event OwnerUpdated(address indexed newOwner);
    /**
     * Emitted when tokens are withdrawn.
     * @param sender - The address of the sender.
     * @param receiver - The address to withdraw to on ZetaChain.
     * @param assets - The amount of assets withdrawn.
     * @param shares - The amount of shares withdrawn.
     * @param destinationChain - The destination chain ID.
     */
    event Withdraw(
        address indexed sender, address indexed receiver, uint256 assets, uint256 shares, uint256 destinationChain
    );
    /**
     * Emitted when the withdraw is paused.
     * @param guardian - The address of the guardian who paused the withdraw.
     * @param time - The timestamp when the withdraw was paused.
     */
    event WithdrawPaused(address indexed guardian, uint256 time);
    /**
     * Emitted when the withdraw is unpaused.
     * @param time - The timestamp when the withdraw was unpaused.
     */
    event WithdrawUnpaused(uint256 time);

    error DepositIsForbidden();
    error InvalidFee();
    error InvalidMessage(bytes);
    error InvalidSignature();
    error NonceIsUsed(address sender, uint256 nonce);
    error NotEVMEntry();
    error NotGateway();
    error NotGuardian();
    error NotOwner();
    error NotYieldMil();
    error SignatureExpired();
    error TransferFailed();
    error VaultIsNotPaused();
    error WithdrawIsForbidden();
    error ZeroAddress();
    error ZeroAssets();
    error ZeroShares();
    error ZeroTokens();

    /**
     * Returns the current version of the contract.
     */
    function VERSION() external view returns (string memory);
    /**
     * Returns the TOKEN contract address.
     */
    function TOKEN() external view returns (IERC20);
    /**
     * Returns the ASSET (AToken) contract address.
     */
    function ASSET() external view returns (IERC20);
    /**
     * Returns the GATEWAY contract address.
     */
    function GATEWAY() external view returns (IGatewayEVM);
    /**
     * Returns the YIELDMIL contract address.
     */
    function YIELDMIL() external view returns (address);
    /**
     * Returns the EVMENTRY contract address.
     */
    function EVMENTRY() external view returns (address);

    /**
     * Deposits tokens into the vault.
     * @param message - The deposit message.
     * @return shares - The amount of minted shares.
     */
    function deposit(bytes calldata message) external returns (uint256 shares);
    /**
     * Withdraws tokens from the vault.
     * @param message - The withdraw message.
     */
    function withdraw(bytes calldata message) external;
    /**
     * Pauses the deposit.
     * @dev Only the guardian can pause the deposit.
     */
    function pauseDeposit() external;
    /**
     * Pauses the withdraw.
     * @dev Only the guardian can pause the withdraw.
     */
    function pauseWithdraw() external;
    /**
     * Unpauses the deposit.
     * @dev Only the owner can unpause the deposit.
     */
    function unpauseDeposit() external payable;
    /**
     * Unpauses the withdraw.
     * @dev Only the owner can unpause the withdraw.
     */
    function unpauseWithdraw() external payable;
    /**
     * Updates guardian's status.
     * @dev Only the owner can update the guardian's status.
     * @param guardian - The address of the guardian.
     * @param status - The status of the guardian.
     */
    function updateGuardian(address guardian, bool status) external payable;
    /**
     * Sets the fee.
     * @dev Only callable by the owner.
     * @param newFee - The new fee.
     */
    function setFee(uint256 newFee) external payable;
    /**
     * Withdraws the accumulated fees.
     * @dev Only callable by the owner.
     * @notice Withdraws in ATokens.
     * @param to - The address to withdraw to.
     */
    function withdrawFees(address to) external payable;
    /**
     * Transfers ownership of the contract.
     * @dev Only callable by the owner.
     * @param newOwner - The new owner.
     */
    function transferOwnership(address newOwner) external payable;
    /**
     * Rescues funds from the contract.
     * @notice For native tokens use address(0).
     * @dev Only callable by the owner.
     * @param to - The address to rescue to.
     * @param token - The token to rescue.
     * @param amount - The amount of funds to rescue.
     */
    function rescueFunds(address to, IERC20 token, uint256 amount) external payable;

    /**
     * Returns the POOL contract address.
     */
    function getPool() external view returns (address);
    /**
     * Returns the fee.
     */
    function getFee() external view returns (uint256);
    /**
     * Returns the owner.
     */
    function getOwner() external view returns (address);
    /**
     * Returns the guardian status.
     * @param guardian - The address of the guardian.
     */
    function isGuardian(address guardian) external view returns (bool);
    /**
     * Returns the last vault balance.
     */
    function getLastVaultBalance() external view returns (uint256);
    /**
     * Returns current free nonce.
     * @param sender - The address of the sender.
     */
    function getNonce(address sender) external view returns (uint256);
    /**
     * Returns the total supply of shares.
     */
    function totalSupply() external view returns (uint256);
    /**
     * Returns the total amount of assets minus the accumulated fees.
     */
    function totalAssets() external view returns (uint256);
    /**
     * Returns the accumulated fees.
     */
    function getAccumulatedFees() external view returns (uint256);
    /**
     * Returns the assets and shares.
     * @param owner - The address of the owner of assets and shares.
     * @return assets - The amount of assets.
     * @return shares - The amount of shares.
     */
    function getAssetsAndShares(address owner) external view returns (uint256 assets, uint256 shares);
}
"
    },
    "src/utils/AaveVaultStorage.sol": {
      "content": "// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

/**
 * @title AaveVaultStorage
 * @author https://github.com/nzmpi
 * @notice A storage contract for the AaveVault
 */
contract AaveVaultStorage {
    // EIP-7201: keccak256(abi.encode(uint256(keccak256("yieldmil.storage.aavevault")) - 1)) & ~bytes32(uint256(0xff))
    bytes32 private constant AAVEVAULT_STORAGE_SLOT = 0xe86928725d42611a4d97f5379bd85d7fa4997f3070cc0d523b2643f8c6d82d00;

    /**
     * A storage struct for the AaveVault.
     * @dev All new fields must be added at the end of the struct.
     * @param fee - The fee.
     * @param accumulatedFees - The accumulated fees.
     * @param lastVaultBalance - The last vault balance of assets.
     * @param totalShares - The total shares.
     * @param owner - The owner of the contract.
     * @param shareBalanceOf - The share balance of each address.
     * @param isDepositPaused - Whether the deposit is paused.
     * @param isWithdrawPaused - Whether the withdraw is paused.
     * @param guardians - The guardians of the contract, that can pause the deposit and/or withdraw.
     * @param nonces - Current free nonce of each address.
     */
    struct Storage {
        uint16 fee;
        uint240 accumulatedFees;
        uint256 lastVaultBalance;
        uint256 totalShares;
        address owner;
        mapping(address => uint256 shares) shareBalanceOf;
        bool isDepositPaused;
        bool isWithdrawPaused;
        mapping(address => bool status) guardians;
        mapping(address => uint256 nonce) nonces;
    }

    /**
     * Returns the storage of the AaveVault.
     */
    function _getStorage() internal pure returns (Storage storage $) {
        assembly ("memory-safe") {
            $.slot := AAVEVAULT_STORAGE_SLOT
        }
    }
}
"
    },
    "src/utils/Types.sol": {
      "content": "// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

enum Protocol {
    Aave
}

/**
 * A struct to store the context of a cross-chain call.
 * @param targetChain - The target chain to which the call is made.
 * @param protocol - The protocol to which the call is made.
 * @param sender - The address of the sender.
 * @param to - The address on behalf of which the deposit is made on an EVM or to which to receive the withdrawal.
 * @param token - The token to transfer.
 * @param amount - The amount to transfer.
 * @param gasLimit - The gas limit for the call.
 * @param nonce - For deposits - the permit2 nonce, for withdrawals - the nonce from the vault.
 * @param destinationChain - The destination chain for withdrawals.
 * @param deadline - The deadline of the signature.
 * @param signature - The signature.
 */
struct CallContext {
    uint256 targetChain;
    Protocol protocol;
    address sender;
    address to;
    address token;
    uint256 amount;
    uint256 gasLimit;
    uint256 nonce;
    uint256 destinationChain;
    uint256 deadline;
    bytes signature;
}
"
